-- 20261101152010_image_takedowns.sql
-- #218: 공식 이미지를 내리는 함수와 이력. 절차는 docs/image-takedown.md, 결정은 ADR 0006.

-- ─────────────────────────────────────────────
-- 1. image_takedowns: 내린 이미지의 이전 URL 과 사유
--    row_id 는 gacha · gacha_items 어느 쪽이든 가리키므로 FK 를 걸지 않는다.
--    요청자 개인정보는 넣지 않는다. note 에는 메일 제목처럼 찾아갈 단서만 적는다.
-- ─────────────────────────────────────────────
create table "public"."image_takedowns" (
  "id"                  bigint generated by default as identity primary key,
  "batch_id"            uuid   not null,
  "source_table"        text   not null check (source_table in ('gacha', 'gacha_items')),
  "row_id"              bigint not null,
  "previous_image_link" text   not null,
  "reason"              text   not null check (reason in ('rights_holder', 'store_review', 'other')),
  "note"                text   not null check (btrim(note) <> ''),
  "created_at"          timestamptz not null default now(),
  "restored_at"         timestamptz
);
create index "image_takedowns_batch_id_idx" on "public"."image_takedowns"(batch_id);

-- 정책 없음 + 권한 회수: 앱은 읽지도 쓰지도 못한다. 운영자는 SQL Editor 로 다룬다.
alter table "public"."image_takedowns" enable row level security;
revoke all on table "public"."image_takedowns" from "anon", "authenticated";
revoke all on sequence "public"."image_takedowns_id_seq" from "anon", "authenticated";

-- ─────────────────────────────────────────────
-- 2. take_down_images: 범위 안의 이미지 URL 을 이력에 남기고 비운다
--    앱은 gacha.image_link 를 보여 주므로 gacha_items 와 함께 비워야 화면에서 사라진다.
--    p_scope: 'gacha'(p_id = 가챠 id), 'anime'(p_id = 작품 id), 'all'(p_id = null)
-- ─────────────────────────────────────────────
create function "public"."take_down_images"(
  p_scope text,
  p_id bigint,
  p_reason text,
  p_note text
)
returns table (takedown_batch uuid, gacha_rows bigint, item_rows bigint)
language plpgsql
set search_path = ''
as $$
declare
  v_batch uuid := gen_random_uuid();
  v_gacha_ids bigint[];
  v_gacha_rows bigint;
  v_item_rows bigint;
begin
  -- 잘못 부른 'gacha' · 'anime' 가 전체를 지우거나, 'all' 이 id 를 무시하지 않게 먼저 막는다
  if p_scope is null or p_scope not in ('gacha', 'anime', 'all') then
    raise exception 'p_scope 는 gacha, anime, all 중 하나여야 한다';
  end if;
  if (p_scope = 'all') <> (p_id is null) then
    raise exception 'gacha · anime 는 p_id 가 필요하고, all 은 p_id 가 null 이어야 한다';
  end if;

  v_gacha_ids := array(
    select g.id from public.gacha g
    where p_scope = 'all'
       or (p_scope = 'gacha' and g.id = p_id)
       or (p_scope = 'anime' and g.anime_id = p_id)
  );

  insert into public.image_takedowns
    (batch_id, source_table, row_id, previous_image_link, reason, note)
  select v_batch, 'gacha', g.id, g.image_link, p_reason, p_note
  from public.gacha g
  where g.id = any(v_gacha_ids) and g.image_link is not null;
  get diagnostics v_gacha_rows = row_count;

  insert into public.image_takedowns
    (batch_id, source_table, row_id, previous_image_link, reason, note)
  select v_batch, 'gacha_items', i.id, i.image_link, p_reason, p_note
  from public.gacha_items i
  where i.gacha_id = any(v_gacha_ids) and i.image_link is not null;
  get diagnostics v_item_rows = row_count;

  update public.gacha g set image_link = null
  where g.id = any(v_gacha_ids) and g.image_link is not null;

  update public.gacha_items i set image_link = null
  where i.gacha_id = any(v_gacha_ids) and i.image_link is not null;

  return query select v_batch, v_gacha_rows, v_item_rows;
end;
$$;

-- 새 함수는 기본으로 anon 도 실행할 수 있어 회수한다 (없으면 RPC 로 노출된다)
revoke all on function "public"."take_down_images"(text, bigint, text, text)
  from public, "anon", "authenticated";
